     1	import { z } from "zod";
     2	import type { RulesPreset } from "../rules.js";
     3	
     4	/**
     5	 * The four rubbing types of §4, in the fixed type order that breaks ties when a theft defaults. A preset with fewer
     6	 * types (the slice's two) uses the first ones of this order.
     7	 */
     8	export const RUBBING_TYPES = ["sun", "moon", "tide", "storm"] as const;
     9	
    10	export const rubbingTypeSchema = z.enum(RUBBING_TYPES);
    11	export type RubbingType = z.infer<typeof rubbingTypeSchema>;
    12	
    13	/** A rubbing's stable id: its type and its copy number from 1, such as `tide-2`. It never changes (§4). */
    14	export const rubbingIdSchema = z.string().regex(/^(sun|moon|tide|storm)-[1-9][0-9]*$/, "a rubbing id is <type>-<copy>");
    15	
    16	/** The position of a type in the fixed type order. */
    17	export function rubbingTypeOrder(type: RubbingType): number {
    18	  return RUBBING_TYPES.indexOf(type);
    19	}
    20	
    21	export function rubbingId(type: RubbingType, copy: number): string {
    22	  if (!Number.isInteger(copy) || copy < 1) throw new RangeError(`a rubbing copy number starts at 1, got ${copy}`);
    23	  return `${type}-${copy}`;
    24	}
    25	
    26	/** The type a rubbing id names, or null for a malformed id. */
    27	export function rubbingTypeOf(id: string): RubbingType | null {
    28	  if (!rubbingIdSchema.safeParse(id).success) return null;
    29	  return id.slice(0, id.indexOf("-")) as RubbingType;
    30	}
    31	
    32	/** The types a preset plays with, in the fixed type order. */
    33	export function presetRubbingTypes(preset: RulesPreset): RubbingType[] {
    34	  if (preset.rubbingTypes > RUBBING_TYPES.length) {
    35	    throw new RangeError(`preset ${preset.id} asks for ${preset.rubbingTypes} rubbing types; there are ${RUBBING_TYPES.length}`);
    36	  }
    37	  return RUBBING_TYPES.slice(0, preset.rubbingTypes);
    38	}
    39	
    40	export interface RubbingDefinition {
    41	  readonly id: string;
    42	  readonly type: RubbingType;
    43	}
    44	
    45	/** Every rubbing of a preset, by type order then copy: `sun-1`, `sun-2`, … (slice: 2 × 4; alpha: 4 × 3). */
    46	export function presetRubbings(preset: RulesPreset): RubbingDefinition[] {
    47	  const copies = preset.rubbings / preset.rubbingTypes;
    48	  if (!Number.isInteger(copies)) throw new RangeError(`preset ${preset.id}: rubbings must split evenly across types`);
    49	  return presetRubbingTypes(preset).flatMap((type) =>
    50	    Array.from({ length: copies }, (_, index) => ({ id: rubbingId(type, index + 1), type })),
    51	  );
    52	}
