     1	import { z } from "zod";
     2	import { formatIssues, type ValidationResult } from "../rules.js";
     3	
     4	/** World ticks per second (§15): the ledger's only clock. */
     5	export const WORLD_TICKS_PER_SECOND = 20;
     6	
     7	const ticks = z.int().nonnegative();
     8	
     9	/** The timings and amounts of §4, §11 and §12 the ledger enforces, in world ticks and gold. */
    10	export const objectiveRulesSchema = z.strictObject({
    11	  /** §4: hold interact this long, uninterrupted, at an unlocked source. */
    12	  collectTicks: z.int().positive(),
    13	  /** §12: one six-second interaction claims one rubbing from a recovery cache. */
    14	  cacheClaimTicks: z.int().positive(),
    15	  /** §4: the winner's theft choice window; without a choice the default applies. */
    16	  theftChoiceTicks: z.int().positive(),
    17	  /** §11: the PvP victory takes this percentage of the loser's gold, rounded down… */
    18	  pvpGoldPercent: z.int().min(0).max(100),
    19	  /** …capped at this much. */
    20	  pvpGoldCap: z.int().nonnegative(),
    21	  /** §11: a win over the same opponent within this long of the previous one pays no gold. */
    22	  repeatWinWindowTicks: ticks,
    23	  /** §11: every player's starting purse. */
    24	  startingGold: z.int().nonnegative(),
    25	  /** §12: a disconnected player's seat stays reserved this long. */
    26	  seatReservationTicks: z.int().positive(),
    27	});
    28	
    29	export type ObjectiveRules = z.infer<typeof objectiveRulesSchema>;
    30	
    31	export const objectiveRules = {
    32	  collectTicks: 6 * WORLD_TICKS_PER_SECOND,
    33	  cacheClaimTicks: 6 * WORLD_TICKS_PER_SECOND,
    34	  theftChoiceTicks: 5 * WORLD_TICKS_PER_SECOND,
    35	  pvpGoldPercent: 20,
    36	  pvpGoldCap: 50,
    37	  repeatWinWindowTicks: 3 * 60 * WORLD_TICKS_PER_SECOND,
    38	  startingGold: 50,
    39	  seatReservationTicks: 60 * WORLD_TICKS_PER_SECOND,
    40	} as const satisfies ObjectiveRules;
    41	
    42	export function validateObjectiveRules(candidate: unknown): ValidationResult<ObjectiveRules> {
    43	  const parsed = objectiveRulesSchema.safeParse(candidate);
    44	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
    45	}
    46	
    47	/**
    48	 * §11's PvP gold: `pvpGoldPercent` of the loser's gold, rounded down, capped at `pvpGoldCap` and never more than the
    49	 * loser has, so a balance never goes negative. Gold is transferred, never minted.
    50	 */
    51	export function pvpGoldTransfer(rules: ObjectiveRules, loserGold: number): number {
    52	  if (!Number.isSafeInteger(loserGold) || loserGold <= 0) return 0;
    53	  const share = Math.floor((loserGold * rules.pvpGoldPercent) / 100);
    54	  return Math.min(share, rules.pvpGoldCap, loserGold);
    55	}
