     1	import { z } from "zod";
     2	import { formatIssues, rulesPresets, type RulesPreset, type ValidationResult } from "../rules.js";
     3	import { presetRubbings, rubbingIdSchema, rubbingTypeOf, rubbingTypeSchema } from "./types.js";
     4	
     5	/**
     6	 * Where a source can stand: an island index of the preset and an integer sub-unit position that the caller takes from
     7	 * the map. The ledger does not know the map; it only keeps the positions with the sources.
     8	 */
     9	export const sourceSiteSchema = z.strictObject({
    10	  island: z.int().nonnegative(),
    11	  x: z.int(),
    12	  y: z.int(),
    13	});
    14	
    15	export type SourceSite = z.infer<typeof sourceSiteSchema>;
    16	
    17	/** A source's id names its island and its place among that island's sources: `source-<island>-<slot>`. */
    18	export function sourceId(island: number, slot: number): string {
    19	  return `source-${island}-${slot}`;
    20	}
    21	
    22	export const assignedSourceSchema = z.strictObject({
    23	  id: z.string().regex(/^source-[0-9]+-[0-9]+$/, "a source id is source-<island>-<slot>"),
    24	  island: z.int().nonnegative(),
    25	  x: z.int(),
    26	  y: z.int(),
    27	  type: rubbingTypeSchema,
    28	  /** The rubbing sealed here at the start of the match. */
    29	  rubbingId: rubbingIdSchema,
    30	});
    31	
    32	export type AssignedSource = z.infer<typeof assignedSourceSchema>;
    33	
    34	interface Issue {
    35	  readonly path: (string | number)[];
    36	  readonly message: string;
    37	}
    38	
    39	/** The island rule shared by sites and assignments: `sourcesPerIsland` sources on each island, and no other island. */
    40	function islandIssues(preset: RulesPreset, islands: readonly number[]): Issue[] {
    41	  const issues: Issue[] = [];
    42	  if (islands.length !== preset.rubbings) {
    43	    issues.push({ path: [], message: `preset ${preset.id} needs ${preset.rubbings} sources, got ${islands.length}` });
    44	  }
    45	  const perIsland = new Map<number, number>();
    46	  islands.forEach((island, index) => {
    47	    if (island >= preset.islands) {
    48	      issues.push({ path: [index, "island"], message: `preset ${preset.id} has islands 0–${preset.islands - 1}` });
    49	    }
    50	    perIsland.set(island, (perIsland.get(island) ?? 0) + 1);
    51	  });
    52	  for (let island = 0; island < preset.islands; island++) {
    53	    const count = perIsland.get(island) ?? 0;
    54	    if (count !== preset.sourcesPerIsland) {
    55	      issues.push({ path: [], message: `island ${island} needs ${preset.sourcesPerIsland} source(s), got ${count}` });
    56	    }
    57	  }
    58	  return issues;
    59	}
    60	
    61	/** The sites the server offers for a preset: exactly `sourcesPerIsland` on each of its islands. */
    62	export function sourceSitesSchema(preset: RulesPreset) {
    63	  return z.array(sourceSiteSchema).superRefine((sites, ctx) => {
    64	    for (const issue of islandIssues(preset, sites.map((site) => site.island))) ctx.addIssue({ code: "custom", ...issue });
    65	  });
    66	}
    67	
    68	export function validateSourceSites(preset: RulesPreset, candidate: unknown): ValidationResult<SourceSite[]> {
    69	  const parsed = sourceSitesSchema(preset).safeParse(candidate);
    70	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
    71	}
    72	
    73	/**
    74	 * The server-controlled assignment of rubbings to sources (§4): the preset's rubbings, each sealed at exactly one
    75	 * source, `sourcesPerIsland` sources on each island, every source id unique and naming its island.
    76	 */
    77	export const sourceAssignmentSchema = z
    78	  .strictObject({
    79	    preset: z.enum(["slice", "alpha"]),
    80	    /** The seed the assignment was drawn from, so it can be reproduced. */
    81	    seed: z.int().nonnegative(),
    82	    sources: z.array(assignedSourceSchema),
    83	  })
    84	  .superRefine((assignment, ctx) => {
    85	    const preset = rulesPresets[assignment.preset];
    86	    const { sources } = assignment;
    87	    for (const issue of islandIssues(preset, sources.map((source) => source.island))) {
    88	      ctx.addIssue({ code: "custom", path: ["sources", ...issue.path], message: issue.message });
    89	    }
    90	    const ids = new Set<string>();
    91	    sources.forEach((source, index) => {
    92	      if (ids.has(source.id)) ctx.addIssue({ code: "custom", path: ["sources", index, "id"], message: `duplicate source id ${source.id}` });
    93	      ids.add(source.id);
    94	      if (!source.id.startsWith(`source-${source.island}-`)) {
    95	        ctx.addIssue({ code: "custom", path: ["sources", index, "id"], message: `source ${source.id} is not on island ${source.island}` });
    96	      }
    97	      if (rubbingTypeOf(source.rubbingId) !== source.type) {
    98	        ctx.addIssue({ code: "custom", path: ["sources", index, "type"], message: `rubbing ${source.rubbingId} is not of type ${source.type}` });
    99	      }
   100	    });
   101	    const expected = presetRubbings(preset).map((rubbing) => rubbing.id).sort();
   102	    const actual = sources.map((source) => source.rubbingId).sort();
   103	    if (expected.join(",") !== actual.join(",")) {
   104	      ctx.addIssue({
   105	        code: "custom",
   106	        path: ["sources"],
   107	        message: `preset ${preset.id} seals each of ${expected.join(", ")} exactly once; got ${actual.join(", ")}`,
   108	      });
   109	    }
   110	  });
   111	
   112	export type SourceAssignment = z.infer<typeof sourceAssignmentSchema>;
   113	
   114	export function validateSourceAssignment(candidate: unknown): ValidationResult<SourceAssignment> {
   115	  const parsed = sourceAssignmentSchema.safeParse(candidate);
   116	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
   117	}
