    49	}
    50	
    51	/** What every operation returns: the next state (the same object when nothing changed) and its result. */
    52	export interface LedgerStep<R> {
    53	  readonly state: LedgerState;
    54	  readonly result: R;
    55	}
    56	
    57	/** Moves made so far by one operation, and the caches it opened. */
    58	export interface Effects {
    59	  readonly transfers: Transfer[];
    60	  readonly cacheIds: string[];
    61	}
    62	
    63	export function noEffects(): Effects {
    64	  return { transfers: [], cacheIds: [] };
    65	}
    66	
    67	function isSafeInteger(value: unknown): value is number {
    68	  return typeof value === "number" && Number.isSafeInteger(value);
    69	}
    70	
    71	export function isPlayerId(value: unknown): value is string {
    72	  return typeof value === "string" && value.length > 0;
    73	}
    74	
    75	export function isPosition(value: unknown): value is Position {
    76	  if (typeof value !== "object" || value === null) return false;
    77	  const { x, y } = value as Record<string, unknown>;
    78	  return isSafeInteger(x) && isSafeInteger(y);
    79	}
    80	
    81	/** A request's tick must be a non-negative integer no earlier than the ledger's latest. */
    82	export function tickRejection(state: LedgerState, tick: unknown): LedgerRejection | null {
    83	  if (!isSafeInteger(tick) || tick < 0) return "invalid-request";
    84	  return tick < state.tick ? "stale-tick" : null;
    85	}
    86	
    87	export function atTick(state: LedgerState, tick: number): LedgerState {
    88	  return tick === state.tick ? state : { ...state, tick };
    89	}
    90	
    91	/** Why a player cannot act in the world right now, if they cannot. */
    92	export function playerRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
    93	  if (!isPlayerId(playerId)) return "invalid-request";
    94	  const player = findPlayer(state, playerId);
    95	  if (!player) return "unknown-player";
    96	  return player.status === "left" ? "player-left" : null;
    97	}
    98	
    99	export function updatePlayer(
   100	  state: LedgerState,
   101	  playerId: string,
   102	  update: (player: LedgerPlayer) => LedgerPlayer,
   103	): LedgerState {
   104	  return { ...state, players: state.players.map((player) => (player.id === playerId ? update(player) : player)) };
   105	}
   106	
   107	/** Moves each listed rubbing to its target, bumping its revision, and drops any cache the moves emptied. */
   108	export function moveRubbings(
   109	  state: LedgerState,
   110	  moves: readonly { readonly rubbingId: string; readonly to: RubbingLocation }[],
   111	  effects: Effects,
   112	): LedgerState {
   113	  if (moves.length === 0) return state;
   114	  const targets = new Map(moves.map((move) => [move.rubbingId, move.to]));
   115	  if (targets.size !== moves.length) throw new Error("a rubbing cannot move twice in one step");
   116	  const rubbings = state.rubbings.map((rubbing): LedgerRubbing => {
   117	    const to = targets.get(rubbing.id);
   118	    if (to === undefined) return rubbing;
   119	    targets.delete(rubbing.id);
   120	    effects.transfers.push({
   121	      rubbingId: rubbing.id,
   122	      from: rubbing.location,
   123	      to,
   124	      revisionBefore: rubbing.revision,
   125	      revisionAfter: rubbing.revision + 1,
   126	    });
   127	    return { ...rubbing, location: to, revision: rubbing.revision + 1 };
   128	  });
   129	  if (targets.size > 0) throw new Error(`unknown rubbings ${[...targets.keys()].join(", ")}`);
   130	  return dropEmptyCaches({ ...state, rubbings });
   131	}
   132	
   133	function dropEmptyCaches(state: LedgerState): LedgerState {
   134	  const used = new Set(
   135	    state.rubbings.flatMap((rubbing) => (rubbing.location.kind === "cache" ? [rubbing.location.cacheId] : [])),
   136	  );
   137	  const caches = state.caches.filter((cache) => used.has(cache.id));
   138	  return caches.length === state.caches.length ? state : { ...state, caches };
   139	}
   140	
   141	/** Opens a recovery cache holding the listed rubbings at a position; with none, no cache appears. */
   142	export function openCache(
   143	  state: LedgerState,
   144	  position: { readonly x: number; readonly y: number },
   145	  rubbingIds: readonly string[],
   146	  tick: number,
   147	  effects: Effects,
   148	): LedgerState {
   149	  if (rubbingIds.length === 0) return state;
   150	  const cache: LedgerCache = { id: `cache-${state.nextCacheNumber}`, x: position.x, y: position.y, createdTick: tick };
   151	  effects.cacheIds.push(cache.id);
   152	  const opened = { ...state, caches: [...state.caches, cache], nextCacheNumber: state.nextCacheNumber + 1 };
   153	  return moveRubbings(
   154	    opened,
   155	    rubbingIds.map((rubbingId) => ({ rubbingId, to: { kind: "cache", cacheId: cache.id } as const })),
   156	    effects,
   157	  );
   158	}
   159	
   160	/**
   161	 * Returns rubbings to a player, or, when that player has left the match, into a recovery cache at the place they
   162	 * left from, so a rubbing never follows a player out of the match.
   163	 */
   164	export function releaseTo(
   165	  state: LedgerState,
   166	  playerId: string,
   167	  rubbingIds: readonly string[],
   168	  tick: number,
   169	  effects: Effects,
   170	): LedgerState {
   171	  const player = findPlayer(state, playerId);
   172	  if (!player) throw new Error(`unknown player ${playerId}`);
   173	  if (player.status === "left") {
   174	    if (player.exit === null) throw new Error(`player ${playerId} left without an exit position`);
   175	    return openCache(state, player.exit, rubbingIds, tick, effects);
   176	  }
   177	  return moveRubbings(
   178	    state,
   179	    rubbingIds.map((rubbingId) => ({ rubbingId, to: { kind: "player", playerId } as const })),
   180	    effects,
   181	  );
   182	}

