    22	
    23	/**
    24	 * - `started`: a new channel, at 0 held ticks.
    25	 * - `held`: one more tick held.
    26	 * - `reset`: the hold was interrupted (a tick without progress), so it counts from 0 again at this tick.
    27	 * - `collected` / `claimed`: the channel completed and the rubbing is the player's.
    28	 * - `failed`: the channel completed but its rubbing had gone or was no longer allowed (see `failure`); nothing moved.
    29	 * - `cancelled`: the channel was dropped.
    30	 */
    31	export type ChannelStatus = "started" | "held" | "reset" | "collected" | "claimed" | "failed" | "cancelled";
    32	
    33	export interface ChannelResult {
    34	  readonly ok: boolean;
    35	  readonly rejection: LedgerRejection | null;
    36	  readonly status: ChannelStatus | null;
    37	  /** Why a completed channel failed. */
    38	  readonly failure: LedgerRejection | null;
    39	  /** The player's channel as it now stands. */
    40	  readonly channel: LedgerChannel | null;
    41	  /** The rubbing collected or claimed. */
    42	  readonly rubbingId: string | null;
    43	  readonly transfers: readonly Transfer[];
    44	}
    45	
    46	function rejected(state: LedgerState, rejection: LedgerRejection, playerId: unknown): LedgerStep<ChannelResult> {
    47	  const channel = typeof playerId === "string" ? (findPlayer(state, playerId)?.channel ?? null) : null;
    48	  return { state, result: { ok: false, rejection, status: null, failure: null, channel, rubbingId: null, transfers: [] } };
    49	}
    50	
    51	function result(
    52	  state: LedgerState,
    53	  playerId: string,
    54	  status: ChannelStatus,
    55	  extra: { failure?: LedgerRejection; rubbingId?: string; transfers?: Transfer[] } = {},
    56	): LedgerStep<ChannelResult> {
    57	  return {
    58	    state,
    59	    result: {
    60	      ok: true,
    61	      rejection: null,
    62	      status,
    63	      failure: extra.failure ?? null,
    64	      channel: findPlayer(state, playerId)?.channel ?? null,
    65	      rubbingId: extra.rubbingId ?? null,
    66	      transfers: extra.transfers ?? [],
    67	    },
    68	  };
    69	}
    70	
    71	/** Why a player cannot start or keep a channel: they must be in the match, connected and out of any duel. */
    72	function actorRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
    73	  const refusal = playerRejection(state, playerId);
    74	  if (refusal) return refusal;
    75	  const id = playerId as string;
    76	  if (findPlayer(state, id)!.status === "disconnected") return "player-disconnected";
    77	  return activeDuelOf(state, id) ? "player-in-duel" : null;
    78	}
    79	
    80	/** Why the channel's rubbing cannot go to the player now, if it cannot. Checked at the start and again at the end. */
    81	function targetRejection(state: LedgerState, playerId: string, channel: LedgerChannel): LedgerRejection | null {
    82	  const rubbing = findRubbing(state, channel.rubbingId);
    83	  if (channel.kind === "collect") {
    84	    const source = findSource(state, channel.sourceId);
    85	    if (!source) return "unknown-source";
    86	    if (!source.unlocked) return "source-locked";
    87	    if (rubbing?.location.kind !== "source" || rubbing.location.sourceId !== source.id) return "source-empty";
    88	  } else {
    89	    if (!findCache(state, channel.cacheId)) return "unknown-cache";
    90	    if (rubbing?.location.kind !== "cache" || rubbing.location.cacheId !== channel.cacheId) return "not-in-cache";
    91	  }
    92	  return heldTypes(state, playerId).includes(rubbing.type) ? "type-held" : null;
    93	}
    94	
    95	function sameTarget(a: LedgerChannel | null, b: LedgerChannel): boolean {
    96	  if (a === null || a.kind !== b.kind || a.rubbingId !== b.rubbingId) return false;
    97	  return a.kind === "collect" ? b.kind === "collect" && a.sourceId === b.sourceId : b.kind === "claim" && a.cacheId === b.cacheId;
    98	}
    99	
   100	function start(state: LedgerState, playerId: string, channel: LedgerChannel, tick: number): LedgerStep<ChannelResult> {
   101	  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId) ?? targetRejection(state, playerId, channel);
   102	  if (bad) return rejected(state, bad, playerId);
   103	  if (sameTarget(findPlayer(state, playerId)!.channel, channel)) return rejected(state, "duplicate", playerId);
   104	  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel })), playerId, "started");
   105	}
   106	
   107	export interface StartCollectRequest {
   108	  readonly playerId: string;
   109	  readonly sourceId: string;
   110	  readonly tick: number;
   111	}
   112	
   113	/**
   114	 * §4: starts holding interact at an unlocked source with its rubbing still sealed there, for a type the player does
   115	 * not hold. Starting replaces any other channel of the player; repeating the same start changes nothing.
   116	 */
   117	export function startCollect(state: LedgerState, request: StartCollectRequest): LedgerStep<ChannelResult> {
   118	  const { playerId, sourceId, tick } = request;
   119	  const source = typeof sourceId === "string" ? findSource(state, sourceId) : undefined;
   120	  if (!source) return rejected(state, tickRejection(state, tick) ?? "unknown-source", playerId);
   121	  return start(state, playerId, { kind: "collect", sourceId, rubbingId: source.rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
   122	}
   123	
   124	export interface StartCacheClaimRequest {
   125	  readonly playerId: string;
   126	  readonly cacheId: string;
   127	  /** §12: one selected rubbing per interaction. */
   128	  readonly rubbingId: string;
   129	  readonly tick: number;
   130	}
   131	
   132	/** §12: starts the interaction that claims one selected rubbing from a cache, for a player missing its type. */
   133	export function startCacheClaim(state: LedgerState, request: StartCacheClaimRequest): LedgerStep<ChannelResult> {
   134	  const { playerId, cacheId, rubbingId, tick } = request;
   135	  if (typeof cacheId !== "string" || typeof rubbingId !== "string") return rejected(state, "invalid-request", playerId);
   136	  return start(state, playerId, { kind: "claim", cacheId, rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
   137	}
   138	
   139	export interface ChannelTickRequest {
   140	  readonly playerId: string;
   141	  readonly tick: number;
   142	}
   143	
   144	/**
   145	 * The player held interact during `tick`. It must be the tick right after the channel's last one; after a gap the
   146	 * hold was interrupted and counts from 0 again. On reaching the rule's ticks the channel completes: the target is
   147	 * checked again, so of two players claiming the same rubbing only the first to complete gets it.
   148	 */
   149	export function progressChannel(state: LedgerState, request: ChannelTickRequest): LedgerStep<ChannelResult> {
   150	  const { playerId, tick } = request;
   151	  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId);
   152	  if (bad) return rejected(state, bad, playerId);
   153	  const channel = findPlayer(state, playerId)!.channel;
   154	  if (channel === null) return rejected(state, "no-channel", playerId);
   155	  if (tick <= channel.lastTick) return rejected(state, "duplicate", playerId);
   156	  const now = atTick(state, tick);
   157	  if (tick > channel.lastTick + 1) {
   158	    const restarted = { ...channel, startTick: tick, lastTick: tick, heldTicks: 0 };
   159	    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: restarted })), playerId, "reset");
   160	  }
   161	  const held = { ...channel, lastTick: tick, heldTicks: channel.heldTicks + 1 };
   162	  const required = channel.kind === "collect" ? state.rules.collectTicks : state.rules.cacheClaimTicks;
   163	  if (held.heldTicks < required) {
   164	    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: held })), playerId, "held");
   165	  }
   166	  const done = updatePlayer(now, playerId, (player) => ({ ...player, channel: null }));
   167	  const failure = targetRejection(done, playerId, channel);
   168	  if (failure) return result(done, playerId, "failed", { failure });
   169	  const effects = noEffects();
   170	  const next = moveRubbings(done, [{ rubbingId: channel.rubbingId, to: { kind: "player", playerId } }], effects);
   171	  return result(next, playerId, channel.kind === "collect" ? "collected" : "claimed", {
   172	    rubbingId: channel.rubbingId,
   173	    transfers: effects.transfers,
   174	  });
   175	}
   176	
   177	/** The player let go of interact, moved or was interrupted: the channel ends and its progress is lost. */
   178	export function cancelChannel(state: LedgerState, request: ChannelTickRequest): LedgerStep<ChannelResult> {
   179	  const { playerId, tick } = request;
   180	  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
   181	  if (bad) return rejected(state, bad, playerId);
   182	  if (findPlayer(state, playerId)!.channel === null) return rejected(state, "no-channel", playerId);
   183	  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel: null })), playerId, "cancelled");
   184	}
