   129	
   130	export interface LeaveRequest {
   131	  readonly playerId: string;
   132	  readonly tick: number;
   133	  /** Where the recovery cache goes: the respawn dock for an expiry, the player's position for a quit (§12). */
   134	  readonly position: Position;
   135	}
   136	
   137	/**
   138	 * §12: at or after the reservation deadline a disconnected player is removed and their remaining rubbings go into a
   139	 * recovery cache at the given position. A rubbing already transferred by a duel they lost is not among them.
   140	 */
   141	export function expireReservation(state: LedgerState, request: LeaveRequest): LedgerStep<PlayerResult> {
   142	  const { playerId, tick, position } = request;
   143	  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
   144	  if (bad) return rejected(state, bad, playerId);
   145	  if (!isPosition(position)) return rejected(state, "invalid-request", playerId);
   146	  const player = findPlayer(state, playerId)!;
   147	  if (player.status !== "disconnected" || player.reservationDeadline === null) return rejected(state, "not-disconnected", playerId);
   148	  if (tick < player.reservationDeadline) return rejected(state, "reservation-active", playerId);
   149	  return leave(state, playerId, position, tick);
   150	}
   151	
   152	/** §12: an explicit quit forfeits a duel in progress, then releases the player's remaining rubbings into a cache. */
   153	export function quitPlayer(state: LedgerState, request: LeaveRequest): LedgerStep<PlayerResult> {
   154	  const { playerId, tick, position } = request;
   155	  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
   156	  if (bad) return rejected(state, bad, playerId);
   157	  if (!isPosition(position)) return rejected(state, "invalid-request", playerId);
   158	  return leave(state, playerId, position, tick);
   159	}
   160	
   161	/**
