   167	function leave(state: LedgerState, playerId: string, position: Position, tick: number): LedgerStep<PlayerResult> {
   168	  const effects = noEffects();
   169	  let next = updatePlayer(atTick(state, tick), playerId, (player) => ({
   170	    ...player,
   171	    status: "left",
   172	    reservationDeadline: null,
   173	    exit: { x: position.x, y: position.y },
