   147	  if (new Set(state.sources.map((source) => source.rubbingId)).size !== expected.length) problems.push("two sources seal the same rubbing");
   148	  for (const [cacheId, count] of caches) if (count === 0) problems.push(`cache ${cacheId} is empty`);
   149	
   150	  let gold = 0;
   151	  for (const player of state.players) {
   152	    if (player.gold < 0) problems.push(`player ${player.id} has ${player.gold} gold`);
   153	    gold += player.gold;
   154	    const inDuels = unresolved.get(player.id) ?? 0;
   155	    if (inDuels > 1) problems.push(`player ${player.id} is in ${inDuels} unresolved duels`);
   156	    if (player.channel !== null && (player.status !== "connected" || inDuels > 0)) {
   157	      problems.push(`player ${player.id} channels while ${inDuels > 0 ? "in a duel" : player.status}`);
   158	    }
   159	    if ((player.status === "disconnected") !== (player.reservationDeadline !== null)) {
   160	      problems.push(`player ${player.id} is ${player.status} with reservation deadline ${player.reservationDeadline}`);
   161	    }
   162	    if ((player.status === "left") !== (player.exit !== null)) problems.push(`player ${player.id} is ${player.status} with exit ${JSON.stringify(player.exit)}`);
   163	    if (player.freshRumors.some((type, index) => !types.includes(type) || player.freshRumors.indexOf(type) !== index)) {
   164	      problems.push(`player ${player.id} has fresh rumors ${player.freshRumors.join(",")}`);
   165	    }
   166	  }
   167	  if (gold !== state.goldIssued) problems.push(`balances sum to ${gold} gold, but ${state.goldIssued} was issued`);
   168	
   169	  for (const duel of state.duels) {
   170	    if (duel.phase === "fighting") {
   171	      if (duel.result !== null || duel.settlement !== null) problems.push(`duel ${duel.id} fights with a result`);
   172	      for (const playerId of duel.players) {
   173	        if (players.get(playerId)?.status === "left") problems.push(`duel ${duel.id} fights on without ${playerId}, who left`);
   174	      }
   175	    } else if (duel.phase === "choosing") {
   176	      if (duel.result?.outcome !== "win" || duel.choiceDeadline === null) problems.push(`duel ${duel.id} chooses without a win`);
   177	      else if (players.get(duel.result.winner ?? "")?.status === "left") problems.push(`duel ${duel.id} waits for a winner who left`);
   178	    } else if (duel.result === null || duel.settlement === null) {
   179	      problems.push(`duel ${duel.id} settled without a result`);
   180	    }
   181	  }
   182	  return problems;
   183	}
   184	
   185	/** Throws with every violation when the ledger breaks its invariant. */
   186	export function assertLedger(state: LedgerState): void {
   187	  const problems = checkLedger(state);
   188	  if (problems.length > 0) throw new Error(`ledger invariant broken:\n${problems.join("\n")}`);
   189	}

