253	    [2, () => apply("unlock", unlockSource, { sourceId: dice.pick(state.sources).id, tick: now })],
254	    [1, () => {
255	      if (state.tick === 0) return;
256	      const stale = state.tick - 1 - dice.int(Math.min(state.tick, 20));
257	      const result = apply("stale", addPlayer, { playerId: `late${stale}`, tick: stale });
258	      expect(result.rejection).toBe("stale-tick");
259	    }],
260	  ];
261	  const total = actions.reduce((sum, [weight]) => sum + weight, 0);
262	
263	  for (let step = 0; step < steps; step++) {
264	    let roll = dice.int(total);
265	    const action = actions.find(([weight]) => (roll -= weight) < 0)!;
266	    action[1]();
267	  }
268	  for (const duel of state.duels) {
269	    if (duel.settlement?.goldSuppressed) count("gold-suppressed");
270	    if (duel.result?.forfeit) count("forfeit");
271	    if (duel.settlement?.stolenRubbingId !== null && duel.settlement?.stolenRubbingId !== undefined) count("theft");
272	    if (duel.result?.outcome === "win" && duel.settlement?.stolenRubbingId === null) count("win-without-theft");
273	  }
